"""Plain-language explanations used by Learn mode and the Glossary page."""

GLOSSARY = {
    # ---- data & EDA
    "EDA": ("Exploratory Data Analysis: looking at data with summaries and charts before modelling, to find its shape, problems and patterns.",
            "Spotting that 'age' is 20% missing before training a model."),
    "Composition": ("How a whole splits into parts (shares, proportions).", "Pie chart of passenger class: 55% third class."),
    "Distribution": ("How the values of one variable are spread out - centre, spread, skew, outliers.", "Histogram of fares: most are cheap, a few are very expensive."),
    "Comparison": ("How a value differs between groups or over time.", "Average bill on Saturday vs Thursday."),
    "Relationship": ("How two or more variables move together.", "Bigger total bill -> bigger tip."),
    "Skewness": ("How lopsided a distribution is. Positive = long right tail, negative = long left tail, ~0 = symmetric.", "Incomes are right-skewed: a few people earn far more than most."),
    "Kurtosis": ("How heavy the tails are compared with a normal curve. High kurtosis = more extreme values.", "Stock returns have high kurtosis: rare crashes and spikes."),
    "Outlier": ("A value far from the rest. The IQR rule flags values below Q1-1.5*IQR or above Q3+1.5*IQR.", "A 512 fare when most fares are under 50."),
    "Correlation": ("A number from -1 to +1 showing how strongly two variables move together. Pearson = linear, Spearman/Kendall = rank-based (monotonic).", "r = 0.68 between bill and tip: strong positive."),
    "Multicollinearity (VIF)": ("When features are highly correlated with each other. VIF > 10 means a feature is almost a copy of others, which makes linear-model coefficients unstable.", "Height in cm and height in inches together."),
    "Mutual information": ("How much knowing a feature reduces uncertainty about the target. Unlike correlation, it also catches non-linear relationships.", "MI is high for 'sex' when predicting Titanic survival."),
    "p-value": ("If there were truly no effect, the probability of seeing a result this extreme. p < 0.05 is the usual 'statistically significant' cut-off.", "ANOVA p = 0.001: fares really differ by class."),
    "Normality test": ("Checks whether data looks normally distributed (Shapiro-Wilk, D'Agostino). p > 0.05 = no evidence against normality.", "Linear regression residuals should be roughly normal."),
    "Data leakage": ("When a feature contains information that won't be available at prediction time (often a copy of the target). It gives fake, too-good scores.", "Using 'alive' to predict 'survived'."),
    # ---- ML basics
    "Machine learning": ("Algorithms that learn patterns from examples instead of being explicitly programmed.", "Learning survival rules from 700 passengers to predict the other 191."),
    "Supervised learning": ("Learning from labelled examples (features -> known target). Classification predicts categories, regression predicts numbers.", "Predict species (classification) or price (regression)."),
    "Unsupervised learning": ("Finding structure in data without a target: clustering, dimensionality reduction.", "Grouping penguins into clusters by body measurements."),
    "Train / validation / test split": ("Train = data the model learns from. Validation = data used to tune choices. Test = untouched data for the final honest score.", "80% train, 20% test; validation carved out of train."),
    "Cross-validation": ("Split the training data into k folds, train on k-1 and validate on the remaining one, rotate k times, average the scores. More reliable than one split.", "5-fold CV gives 5 scores: 0.84, 0.86, 0.83, 0.85, 0.87."),
    "Stratification": ("Keeping class proportions the same in every split.", "If 38% survived overall, each fold also has ~38% survivors."),
    "Scaling": ("Putting numeric features on comparable ranges. Standard = mean 0, std 1; MinMax = 0..1; Robust = uses median/IQR (outlier-resistant). Needed for KNN, SVM, linear models, neural nets.", "Age (0-80) and fare (0-512) scaled to similar ranges."),
    "Encoding": ("Turning categories into numbers. One-Hot = one 0/1 column per level; Ordinal = one integer per level.", "sex -> sex_female, sex_male."),
    "Imputation": ("Filling in missing values (mean, median, most frequent).", "Missing age -> median age 28."),
    "Class imbalance": ("When one class is much rarer than another. Accuracy becomes misleading; use F1/ROC-AUC, class weights or resampling (SMOTE).", "1% fraud vs 99% normal."),
    "SMOTE": ("Synthetic Minority Over-sampling: creates new synthetic examples of the rare class by interpolating between neighbours. Applied only to training folds.", "Turning 50 fraud cases into 500 synthetic-plus-real ones."),
    "Hyperparameter": ("A setting chosen before training (not learned from data).", "max_depth of a tree, learning rate, number of epochs."),
    "Grid / Random search": ("Grid search tries every combination of hyperparameters; random search samples combinations - faster on large grids.", "Trying max_depth in {3,5,8} x min_samples_leaf in {1,5,20}."),
    "Regularization": ("A penalty on model complexity to reduce overfitting. L2 (Ridge) shrinks weights; L1 (Lasso) can set them to zero.", "Ridge alpha=10 makes coefficients smaller."),
    "Overfitting": ("The model memorises training data (including noise) and does worse on new data. Sign: train score >> validation score.", "Train accuracy 99%, test accuracy 78%."),
    "Underfitting": ("The model is too simple to capture the pattern. Sign: both train and validation scores are low.", "A straight line fitted to a curve."),
    "Bias-variance trade-off": ("Bias = error from wrong assumptions (underfitting). Variance = error from sensitivity to the training sample (overfitting). Good models balance both.", "Deep trees: low bias, high variance."),
    "Learning curve": ("Score vs number of training rows. If validation keeps rising, more data helps; a big persistent gap means overfitting.", ""),
    "Validation curve": ("Score vs one hyperparameter value. Shows the sweet spot between under- and overfitting.", "Validation score peaks at max_depth = 5."),
    # ---- metrics
    "Accuracy": ("Share of predictions that are correct. Misleading when classes are imbalanced.", "160 right out of 179 = 89%."),
    "Precision": ("Of everything predicted positive, how many really were positive. High precision = few false alarms.", "Of 50 predicted survivors, 40 survived -> 80%."),
    "Recall": ("Of all real positives, how many the model found. High recall = few misses.", "Of 69 real survivors, the model found 50 -> 72%."),
    "F1 score": ("Harmonic mean of precision and recall - one number that balances both.", "P=0.8, R=0.72 -> F1=0.76."),
    "ROC-AUC": ("Area under the ROC curve: the probability the model ranks a random positive higher than a random negative. 0.5 = random, 1.0 = perfect.", "AUC 0.86 = good separation."),
    "Confusion matrix": ("Table of actual vs predicted classes: true positives, false positives, false negatives, true negatives.", ""),
    "Decision threshold": ("Probability above which a row is labelled positive (default 0.5). Lowering it raises recall but lowers precision.", "Threshold 0.3 for a cancer screen to miss fewer cases."),
    "Calibration": ("Whether predicted probabilities match reality. A calibrated model's '70%' cases happen 70% of the time.", ""),
    "R2": ("Share of the target's variance explained by the model. 1 = perfect, 0 = no better than predicting the mean, negative = worse.", "R2 = 0.8: 80% of price variation explained."),
    "MAE / RMSE": ("Mean absolute error = average size of errors. RMSE squares errors first, so it punishes big misses more.", "MAE 0.75 dollars on a tip prediction."),
    "Residual": ("Actual minus predicted. Residuals should look like random noise around 0.", ""),
    "Feature importance": ("How much each feature contributes to predictions. Permutation importance = drop in score when the feature is shuffled.", ""),
    "Partial dependence": ("The average predicted value as one feature changes, others held fixed.", "Survival probability falls as age rises."),
    "SHAP": ("A game-theory method that splits each prediction into contributions from each feature.", "This passenger: +0.3 for being female, -0.1 for 3rd class."),
    # ---- clustering
    "K-Means": ("Clustering that places k centres and assigns each row to the nearest centre, repeating until stable.", ""),
    "Elbow method": ("Plot inertia (within-cluster spread) vs k and pick the k where improvement slows down - the 'elbow'.", ""),
    "Silhouette score": ("How well each point fits its own cluster vs the next nearest one. -1..1, higher is better.", "0.5 = reasonably separated clusters."),
    "DBSCAN": ("Density-based clustering: finds dense regions, labels sparse points as noise (-1), no need to choose k.", ""),
    "PCA": ("Principal Component Analysis: rotates data to new axes that capture the most variance, used to compress or visualise data.", "2 components keep 85% of the variance."),
    "t-SNE": ("A non-linear 2D projection that keeps similar points close together - good for visualising clusters, not for distances.", ""),
    # ---- deep learning
    "Deep learning": ("Machine learning with neural networks made of many layers that learn features automatically.", ""),
    "Neural network (MLP)": ("Layers of neurons; each neuron computes a weighted sum of its inputs plus a bias, then applies an activation function. An MLP stacks fully connected (dense) layers.", "Input(20) -> Dense(64) -> Dense(32) -> Output(1)."),
    "Neuron / unit": ("One node in a layer: output = activation(w1*x1 + w2*x2 + ... + b).", ""),
    "Weights & biases": ("The numbers the network learns. Training adjusts them to reduce the loss.", "A 20->64 layer has 20*64 weights + 64 biases = 1,344 parameters."),
    "Activation function": ("A non-linear function applied after each layer so the network can learn curves, not just straight lines. ReLU = max(0, x) is the default.", "ReLU, LeakyReLU, Tanh, Sigmoid, GELU."),
    "Epoch": ("One complete pass through the entire training set. Training usually runs for many epochs.", "With 569 rows, one epoch = the model has seen all 569 once."),
    "Batch / batch size": ("A small group of rows processed together before one weight update. Smaller batches = noisier but more frequent updates.", "batch_size = 32."),
    "Iteration / step": ("One weight update = one batch. Steps per epoch = ceil(rows / batch size).", "569 rows / 32 = 18 steps per epoch; 100 epochs = 1,800 iterations."),
    "Loss function": ("A number that measures how wrong the predictions are; training minimises it. BCE for binary, Cross-Entropy for multiclass, MSE/Huber for regression.", ""),
    "Gradient descent": ("Repeatedly nudging weights in the direction that reduces the loss. The gradient tells which direction and how steep.", ""),
    "Backpropagation": ("The algorithm that computes the gradient of the loss with respect to every weight, layer by layer from output back to input.", ""),
    "Learning rate": ("Step size of each weight update. Too high = loss explodes or bounces; too low = painfully slow learning.", "Adam default 0.001."),
    "Optimizer": ("The update rule. SGD = plain gradient steps; Momentum = keeps velocity; Adam/AdamW = adaptive per-weight step sizes (good default); RMSprop = adaptive by recent gradient size.", ""),
    "Learning-rate scheduler": ("Changes the learning rate during training: StepLR halves it every few epochs, ReduceLROnPlateau lowers it when validation stops improving, Cosine smoothly decays it.", ""),
    "Dropout": ("Randomly switches off a fraction of neurons during each training step so the network can't rely on any single one - a regulariser against overfitting.", "dropout = 0.2 drops 20% of units."),
    "Batch normalization": ("Normalises each layer's outputs within a batch, which stabilises and speeds up training.", ""),
    "Weight decay": ("L2 regularisation for neural nets: pulls weights toward zero each step.", "weight_decay = 1e-4."),
    "Early stopping": ("Stop training when validation loss hasn't improved for 'patience' epochs, and restore the best weights.", "patience = 10: stop after 10 epochs with no improvement."),
    "Gradient clipping": ("Caps the size of gradients to prevent exploding updates.", ""),
    "Vanishing / exploding gradients": ("Gradients that shrink to ~0 (learning stalls) or blow up (loss becomes NaN) as they flow back through many layers.", ""),
    "Train vs validation loss": ("Both falling = learning. Train falling but validation rising = overfitting. Both flat and high = underfitting or LR too low.", ""),
}
